package com.bank.rebalance.sim;

import com.bank.rebalance.model.ConsumerNode;
import java.util.*;

public class RebalanceSimulator {
    private final int numPartitions;
    private final List<ConsumerNode> consumers = new ArrayList<>();

    public RebalanceSimulator(int numPartitions) { this.numPartitions = numPartitions; }

    public void addConsumer(String id) { consumers.add(new ConsumerNode(id)); }

    // Initial even assignment (range style).
    public void assignInitial() {
        for (ConsumerNode c : consumers) c.getPartitions().clear();
        for (int p = 0; p < numPartitions; p++) {
            consumers.get(p % consumers.size()).getPartitions().add(p);
        }
    }

    // Remove a consumer and rebalance under the chosen protocol.
    // Returns the number of partitions that were paused (revoked) during rebalance.
    public int removeConsumerAndRebalance(String id, Protocol protocol) {
        ConsumerNode leaving = consumers.stream()
            .filter(c -> c.getId().equals(id)).findFirst().orElseThrow();
        Set<Integer> orphaned = new TreeSet<>(leaving.getPartitions());
        consumers.remove(leaving);

        if (protocol == Protocol.EAGER) {
            // Stop-the-world: revoke EVERYTHING, then reassign from scratch.
            int paused = numPartitions; // all partitions pause
            assignInitial();
            return paused;
        } else {
            // Cooperative-sticky: keep existing owners, only move orphaned partitions.
            int paused = orphaned.size(); // only orphaned partitions pause
            int idx = 0;
            for (int p : orphaned) {
                consumers.get(idx % consumers.size()).getPartitions().add(p);
                idx++;
            }
            return paused;
        }
    }

    public List<ConsumerNode> getConsumers() { return consumers; }
}
