package com.bank.rebalance;

import com.bank.rebalance.sim.Protocol;
import com.bank.rebalance.sim.RebalanceSimulator;
import java.util.logging.*;

public class RebalanceDemo {
    private static final Logger log = Logger.getLogger(RebalanceDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        runScenario(Protocol.EAGER);
        runScenario(Protocol.COOPERATIVE_STICKY);
    }

    private static void runScenario(Protocol protocol) {
        RebalanceSimulator sim = new RebalanceSimulator(12);
        for (int i = 0; i < 4; i++) sim.addConsumer("settle-" + i);
        sim.assignInitial();
        log.info("Protocol=" + protocol + " initial: " + sim.getConsumers());

        int paused = sim.removeConsumerAndRebalance("settle-2", protocol);
        if (protocol == Protocol.EAGER) {
            log.warning("EAGER: " + paused + " of 12 partitions paused (stop-the-world).");
        } else {
            log.info("COOPERATIVE: only " + paused + " partitions paused; rest kept running.");
        }
        log.info("After rebalance: " + sim.getConsumers());
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
